UPDATE creator_backfill_log__new SET event_id = CASE WHEN event_id = 0 THEN 0 ELSE COALESCE(COALESCE((SELECT new_id FROM _idmig_map_events WHERE old_key = CAST(event_id AS TEXT)), CASE WHEN EXISTS (SELECT 1 FROM events WHERE id = event_id) THEN event_id END), 0) END, tenant = CASE WHEN tenant IS NULL THEN 0 WHEN (tenant = '' OR tenant = 0) THEN 0 ELSE COALESCE(COALESCE((SELECT new_id FROM _idmig_guild WHERE old_key = CAST(tenant AS TEXT)), CASE WHEN EXISTS (SELECT 1 FROM tenants WHERE id = tenant) THEN tenant END), 0) END;
DELETE FROM user_oauth__stage WHERE (user_id IS NOT NULL AND NOT (user_id = '' OR user_id = 0) AND COALESCE((SELECT new_id FROM _idmig_user WHERE old_key = CAST(user_id AS TEXT)), CASE WHEN EXISTS (SELECT 1 FROM users WHERE id = user_id) THEN user_id END) IS NULL);
UPDATE user_oauth__stage SET user_id = CASE WHEN user_id IS NULL THEN NULL WHEN (user_id = '' OR user_id = 0) THEN 0 ELSE COALESCE((SELECT new_id FROM _idmig_user WHERE old_key = CAST(user_id AS TEXT)), CASE WHEN EXISTS (SELECT 1 FROM users WHERE id = user_id) THEN user_id END) END;
DELETE FROM guild_custom_domains__stage WHERE (tenant IS NULL OR (NOT (tenant = '' OR tenant = 0) AND COALESCE((SELECT new_id FROM _idmig_guild WHERE old_key = CAST(tenant AS TEXT)), CASE WHEN EXISTS (SELECT 1 FROM tenants WHERE id = tenant) THEN tenant END) IS NULL));
UPDATE guild_custom_domains__stage SET tenant = CASE WHEN tenant IS NULL THEN NULL WHEN (tenant = '' OR tenant = 0) THEN 0 ELSE COALESCE((SELECT new_id FROM _idmig_guild WHERE old_key = CAST(tenant AS TEXT)), CASE WHEN EXISTS (SELECT 1 FROM tenants WHERE id = tenant) THEN tenant END) END, created_by_user_id = CASE WHEN created_by_user_id IS NULL THEN NULL WHEN (created_by_user_id = '' OR created_by_user_id = 0) THEN 0 ELSE COALESCE(COALESCE((SELECT new_id FROM _idmig_user WHERE old_key = CAST(created_by_user_id AS TEXT)), CASE WHEN EXISTS (SELECT 1 FROM users WHERE id = created_by_user_id) THEN created_by_user_id END), 0) END;
DELETE FROM guild_officer_grants__new WHERE (tenant IS NULL OR (NOT (tenant = '' OR tenant = 0) AND COALESCE((SELECT new_id FROM _idmig_guild WHERE old_key = CAST(tenant AS TEXT)), CASE WHEN EXISTS (SELECT 1 FROM tenants WHERE id = tenant) THEN tenant END) IS NULL)) OR (user_id IS NOT NULL AND NOT (user_id = '' OR user_id = 0) AND COALESCE((SELECT new_id FROM _idmig_user WHERE old_key = CAST(user_id AS TEXT)), CASE WHEN EXISTS (SELECT 1 FROM users WHERE id = user_id) THEN user_id END) IS NULL);
UPDATE guild_officer_grants__new SET tenant = CASE WHEN tenant IS NULL THEN NULL WHEN (tenant = '' OR tenant = 0) THEN 0 ELSE COALESCE((SELECT new_id FROM _idmig_guild WHERE old_key = CAST(tenant AS TEXT)), CASE WHEN EXISTS (SELECT 1 FROM tenants WHERE id = tenant) THEN tenant END) END, user_id = CASE WHEN user_id IS NULL THEN NULL WHEN (user_id = '' OR user_id = 0) THEN 0 ELSE COALESCE((SELECT new_id FROM _idmig_user WHERE old_key = CAST(user_id AS TEXT)), CASE WHEN EXISTS (SELECT 1 FROM users WHERE id = user_id) THEN user_id END) END;

