-- Phase F: platform-admin roster rewrite (dual-form, as in 0036).
UPDATE settings SET value = (
  SELECT json_group_array(CAST(COALESCE((SELECT new_id FROM _idmig_user WHERE old_key = CAST(je.value AS TEXT)), CASE WHEN EXISTS (SELECT 1 FROM users WHERE id = je.value) THEN je.value END) AS TEXT))
  FROM json_each(settings.value) je
) WHERE tenant = 0 AND key = 'platform_admin_discord_ids' AND json_valid(value);

